96	function convertContext(configJson: ConfigJson): ContextYaml[] {
97	  const context: ContextYaml[] =
98	    configJson.contextProviders?.map((ctx) => {
99	      // ctx providers that weren't given official blocks
100	      if (
101	        ["web", "debugger", "issue", "database", "google", "http"].includes(
102	          ctx.name,
103	        )
104	      ) {
105	        return {
106	          provider: ctx.name,
107	          params: ctx.params,
108	        };
109	      }
110	      return {
111	        uses: `continuedev/${ctx.name === "open" ? "open-files" : ctx.name}-context`,
112	        with: ctx.params,
113	      };
114	    }) ?? [];
115	
116	  return context;
